from __future__ import annotations

import base64
from dataclasses import dataclass
from datetime import datetime, timezone
import json
import mimetypes
from pathlib import Path
import random
from threading import Lock
import time
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

from .io import sha256_text


API_ROOT = "https://generativelanguage.googleapis.com/v1beta"
PROMPT_VERSION = "kl-p4-short-answer-v1"
SYSTEM_INSTRUCTION = (
    "Answer the visual question using only the supplied visual evidence. "
    "If the evidence is insufficient, answer unknown. Return a short answer without explanation."
)
_BASE_GENERATION_CONFIG = {
    "temperature": 0,
    "maxOutputTokens": 512,
    "responseMimeType": "application/json",
    "responseSchema": {
        "type": "OBJECT",
        "properties": {"answer": {"type": "STRING"}},
        "required": ["answer"],
    },
}


def generation_config(model_id: str) -> dict:
    config = json.loads(json.dumps(_BASE_GENERATION_CONFIG))
    config["thinkingConfig"] = {
        "thinkingBudget": 128 if model_id == "gemini-2.5-pro" else 0
    }
    return config


@dataclass(frozen=True)
class GeminiResult:
    status: str
    raw_model_answer: str
    raw_response: dict | None
    latency_ms: float
    usage: dict
    attempts: int
    retries: int
    error: dict | None
    cache_hit: bool


class DailyQuotaExhausted(RuntimeError):
    def __init__(self, model_id: str, message: str) -> None:
        super().__init__(message)
        self.model_id = model_id


def request_parts(
    question: str,
    mode: str,
    *,
    image_path: Path | None = None,
    lens_text: str | None = None,
) -> list[dict]:
    if mode == "native_vision":
        if image_path is None:
            raise ValueError("native_vision requires image_path")
        mime = mimetypes.guess_type(image_path.name)[0] or "image/jpeg"
        parts = [
            {
                "inlineData": {
                    "mimeType": mime,
                    "data": base64.b64encode(image_path.read_bytes()).decode("ascii"),
                }
            }
        ]
        evidence = "Visual evidence is the attached image."
    elif mode in {"lens_compact", "lens_balanced", "lens_detailed"}:
        if lens_text is None:
            raise ValueError(f"{mode} requires lens_text")
        parts = []
        evidence = f"Visual evidence:\n{lens_text}"
    elif mode == "no_visual":
        parts = []
        evidence = "Visual evidence: none."
    else:
        raise ValueError(f"unknown benchmark mode: {mode}")
    parts.append({"text": f"{evidence}\nQuestion: {question}"})
    return parts


def cache_key(
    model_id: str,
    image_sha256: str,
    question_id: str,
    mode: str,
    lens_description_sha256: str | None,
    repeat_index: int,
) -> str:
    value = {
        "model_id": model_id,
        "image_sha256": image_sha256,
        "question_id": question_id,
        "mode": mode,
        "lens_description_sha256": lens_description_sha256,
        "prompt_version": PROMPT_VERSION,
        "generation_config": generation_config(model_id),
        "repeat_index": repeat_index,
    }
    return sha256_text(json.dumps(value, sort_keys=True, separators=(",", ":")))


class GeminiClient:
    def __init__(self, api_key: str, cache_root: Path, *, max_retries: int = 4) -> None:
        if not api_key:
            raise ValueError("Gemini API key is required")
        self._api_key = api_key
        self.cache_root = cache_root
        self.max_retries = max_retries
        self._exhausted_models: set[str] = set()
        self._quota_lock = Lock()
        self.quota_events: dict[str, str] = {}

    def list_models(self) -> dict:
        request = Request(
            f"{API_ROOT}/models?pageSize=1000",
            headers={"x-goog-api-key": self._api_key},
        )
        with urlopen(request, timeout=60) as response:
            return json.load(response)

    def generate(
        self,
        *,
        model_id: str,
        image_sha256: str,
        question_id: str,
        question: str,
        mode: str,
        image_path: Path | None,
        lens_text: str | None,
        lens_description_sha256: str | None,
        repeat_index: int = 0,
    ) -> GeminiResult:
        with self._quota_lock:
            if model_id in self._exhausted_models:
                raise DailyQuotaExhausted(model_id, "daily request quota already exhausted")
        key = cache_key(
            model_id,
            image_sha256,
            question_id,
            mode,
            lens_description_sha256,
            repeat_index,
        )
        cache_path = self.cache_root / f"{key}.json"
        if cache_path.is_file():
            value = json.loads(cache_path.read_text(encoding="utf-8"))
            value.pop("cached_at_utc", None)
            value.pop("cache_key", None)
            return GeminiResult(**value, cache_hit=True)
        body = {
            "systemInstruction": {"parts": [{"text": SYSTEM_INSTRUCTION}]},
            "contents": [
                {
                    "role": "user",
                    "parts": request_parts(
                        question,
                        mode,
                        image_path=image_path,
                        lens_text=lens_text,
                    ),
                }
            ],
            "generationConfig": generation_config(model_id),
        }
        payload = json.dumps(body, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        attempts = 0
        retries = 0
        started = time.perf_counter()
        response_data = None
        error = None
        while attempts <= self.max_retries:
            attempts += 1
            response_data = None
            try:
                request = Request(
                    f"{API_ROOT}/models/{model_id}:generateContent",
                    data=payload,
                    headers={
                        "x-goog-api-key": self._api_key,
                        "Content-Type": "application/json",
                    },
                    method="POST",
                )
                with urlopen(request, timeout=180) as response:
                    response_data = json.load(response)
                has_text = any(
                    part.get("text")
                    for candidate in response_data.get("candidates", [])
                    for part in candidate.get("content", {}).get("parts", [])
                )
                if has_text:
                    break
                error = {"type": "empty_answer"}
            except HTTPError as exc:
                raw = exc.read().decode("utf-8", errors="replace")
                try:
                    message = json.loads(raw).get("error", {}).get("message", raw[:500])
                except json.JSONDecodeError:
                    message = raw[:500]
                error = {"type": "http", "code": exc.code, "message": message}
                if exc.code == 429 and "generate_requests_per_model_per_day" in message:
                    with self._quota_lock:
                        self._exhausted_models.add(model_id)
                        self.quota_events[model_id] = message
                    raise DailyQuotaExhausted(model_id, message) from exc
                if exc.code != 429 and not 500 <= exc.code < 600:
                    break
            except (URLError, TimeoutError, OSError) as exc:
                error = {"type": "network", "message": str(exc)}
            if attempts <= self.max_retries:
                retries += 1
                time.sleep(min(30.0, (2 ** (attempts - 1)) + random.random()))
        latency_ms = (time.perf_counter() - started) * 1000
        if response_data is None:
            result = {
                "status": "request_failed",
                "raw_model_answer": "",
                "raw_response": None,
                "latency_ms": latency_ms,
                "usage": {},
                "attempts": attempts,
                "retries": retries,
                "error": error,
            }
        else:
            raw_answer = "".join(
                part.get("text", "")
                for candidate in response_data.get("candidates", [])
                for part in candidate.get("content", {}).get("parts", [])
            )
            result = {
                "status": "ok" if raw_answer else "parse_failed",
                "raw_model_answer": raw_answer,
                "raw_response": response_data,
                "latency_ms": latency_ms,
                "usage": response_data.get("usageMetadata", {}),
                "attempts": attempts,
                "retries": retries,
                "error": None if raw_answer else {"type": "empty_answer"},
            }
        if result["status"] != "ok":
            return GeminiResult(**result, cache_hit=False)
        self.cache_root.mkdir(parents=True, exist_ok=True)
        cache_value = {
            **result,
            "cached_at_utc": datetime.now(timezone.utc).isoformat(),
            "cache_key": key,
        }
        cache_path.write_text(
            json.dumps(cache_value, ensure_ascii=False, separators=(",", ":"), allow_nan=False),
            encoding="utf-8",
            newline="\n",
        )
        cache_value.pop("cached_at_utc")
        cache_value.pop("cache_key")
        return GeminiResult(**cache_value, cache_hit=False)
